// Pricing rules. Pure functions, no React. All money is integer cents.

export type PlanId = "pro";

export type PlanConfig = {
  id: PlanId;
  unitPriceCents: number; // per seat per month
  minSeats: number;
  maxSeats: number;
};

export const PLAN_CONFIGS: Record<PlanId, PlanConfig> = {
  pro: { id: "pro", unitPriceCents: 1900, minSeats: 1, maxSeats: 50 },
};

export type Quote = {
  seats: number; // clamped to the plan's range
  unitPriceCents: number;
  subtotalCents: number;
  totalCents: number;
};

export function clampSeats(planId: PlanId, seats: number): number {
  const { minSeats, maxSeats } = PLAN_CONFIGS[planId];
  if (!Number.isFinite(seats)) return minSeats;
  return Math.min(maxSeats, Math.max(minSeats, Math.trunc(seats)));
}

export function calculateQuote(planId: PlanId, seats: number): Quote {
  const { unitPriceCents } = PLAN_CONFIGS[planId];
  const clamped = clampSeats(planId, seats);
  const subtotalCents = unitPriceCents * clamped;
  // Pro has no discounts, so total equals subtotal.
  return { seats: clamped, unitPriceCents, subtotalCents, totalCents: subtotalCents };
}

export function formatCents(cents: number): string {
  return `$${(cents / 100).toFixed(2)}`;
}

"use client";

import { useState } from "react";
import PlanCard, { type PlanContent } from "@/components/PlanCard";
import { PLAN_CONFIGS, calculateQuote, clampSeats, formatCents, type PlanId } from "@/lib/pricing";

// Owns the seat count for one plan, so each card is independent.
export default function PricingCard({ planId, content }: { planId: PlanId; content: PlanContent }) {
  const { minSeats, maxSeats } = PLAN_CONFIGS[planId];
  const [seats, setSeats] = useState(minSeats);
  const quote = calculateQuote(planId, seats);

  return (
    <PlanCard
      plan={{
        ...content,
        pricePerSeat: formatCents(quote.unitPriceCents),
        seats: quote.seats,
        subtotal: formatCents(quote.subtotalCents),
        total: formatCents(quote.totalCents),
      }}
      onDecrease={() => setSeats((s) => clampSeats(planId, s - 1))}
      onIncrease={() => setSeats((s) => clampSeats(planId, s + 1))}
      canDecrease={quote.seats > minSeats}
      canIncrease={quote.seats < maxSeats}
    />
  );
}

